const clean=(value,max=500)=>String(value??'').trim().slice(0,max);

export function buildAgentPrompt(question,{connected=false,includeBrief=false,brief={}}={}) {
  const message=clean(question,5000);
  if(!message)throw new Error('Write a question first.');
  const rules=['Work only with private businesses, independent professionals and private-sector career opportunities.','Separate supplied facts from assumptions. Do not invent prospects, buying intent, source checks, conversations or results.','Suggest concrete next steps; do not send messages or change my workspace without asking.'];
  if(connected)rules.unshift('Use my connected Pull GTM MCP tools to read my saved workspace only if useful for this question. Respect the tool permissions and show evidence gaps.');
  else rules.unshift('You do not have access to my Pull GTM workspace. Ask for missing context instead of claiming to have read it.');
  const context=includeBrief?Object.entries({workspace:brief.identity,goal:brief.persona,offer:brief.offer,roles:brief.roles,industries:brief.industries,markets:brief.countries}).map(([key,value])=>[key,clean(value,key==='offer'?500:160)]).filter(([,value])=>value).map(([key,value])=>`${key}: ${value}`).join('\n'):'';
  return `I am using Pull GTM. ${message}\n\n${rules.map((rule,i)=>`${i+1}. ${rule}`).join('\n')}${context?`\n\nMy brief (supplied by me, not independently verified):\n${context}`:''}`;
}

export function localGuidance({mode='empty',items=[],reviewed=0,persona='business'}={}) {
  const counts={fit:items.filter(item=>item.status==='fit').length,review:items.filter(item=>item.status==='review').length,excluded:items.filter(item=>item.status==='excluded').length};
  if(mode==='empty'||!items.length)return {...counts,title:'Start with your own list',detail:persona==='career'?'Import opportunities or contacts you gathered lawfully, then define the roles you want.':'Import a list you own, then define the audience that matters to you.',action:'Import a list',target:'import'};
  if(mode==='example')return {...counts,title:'Explore the method',detail:'These records are fictional. Review a sample to see how Pull separates fit from evidence.',action:'Review examples',target:'prospects'};
  if(counts.review)return {...counts,title:'Close the evidence gaps',detail:`${counts.review} ${counts.review===1?'record needs':'records need'} a closer look before you rely on them.`,action:'Review evidence',target:'prospects'};
  if(counts.fit&&!reviewed)return {...counts,title:'Choose who is worth reaching',detail:`${counts.fit} ${counts.fit===1?'record matches':'records match'} your rules. Check the source and approve each one yourself.`,action:'Review matches',target:'prospects'};
  if(reviewed)return {...counts,title:'Make the next message count',detail:`You reviewed ${reviewed} ${reviewed===1?'prospect':'prospects'}. Prepare a specific, editable message based on verified facts.`,action:'Prepare outreach',target:'drafts'};
  return {...counts,title:'Refine the audience',detail:'Your imported records do not yet match the current rules. Review the criteria and source details.',action:'Adjust audience',target:'prospects'};
}

export function renderAgentAIView({cloud,agentState,state,assistantState,items,escape:e,icon}) {
  const active=Boolean(cloud.user&&cloud.verified&&agentState.tokens.some(token=>token.scopes?.includes('chat:relay')));
  const saved=Boolean(cloud.revision>0&&!cloud.dirty);
  const canUseTools=active&&saved;
  const listening=canUseTools&&agentState.tokens.some(token=>token.scopes?.includes('chat:relay')&&token.last_chat_poll_at&&Date.now()-Date.parse(token.last_chat_poll_at)<120000);
  const guide=localGuidance({mode:state.mode,items,reviewed:state.shortlist.length,persona:state.persona});
  const badge=listening?'Your agent is checking for questions':canUseTools?'Start the relay in your agent':'Useful before you connect';
  const prompts=[['Refine my audience','prospects'],['Review the gaps','shield'],['Keep it in my voice','drafts']];
  const transcript=(assistantState.messages||[]).length?(assistantState.messages||[]).map(m=>`<article class="ai-message user"><span class="ai-message-label">You · ${e(new Date(m.created_at).toLocaleTimeString())}</span><p>${e(m.question)}</p></article>${m.status==='answered'&&m.answer?`<article class="ai-message assistant"><span class="ai-message-label">Your agent</span><p>${e(m.answer)}</p></article>`:`<div class="ai-thinking" role="status"><span></span><span></span><span></span>${new Date(m.expires_at)<=new Date()?'Question expired without an answer':m.status==='claimed'?'Your agent is working on this':'Waiting for your agent to check Pull'}</div>`}`).join(''):`<div class="ai-welcome"><span class="ai-greeting">YOUR WORKSPACE, WITH AI</span><h2>What would you like to<br><em>work on?</em></h2><p>Ask about an audience, a source, or a message. Your connected agent can reply here in your own voice.</p><div class="ai-prompts">${prompts.map(([label,glyph],i)=>`<button data-ai-prompt="${i}"><span class="ai-prompt-icon">${icon(glyph)}</span><strong>${e(label)}</strong>${icon('arrow')}</button>`).join('')}</div><p class="agent-ai-quiet-next">${e(guide.title)}. ${e(guide.detail)} <button class="link-button" ${guide.target==='import'?'data-action="import"':`data-view="${e(guide.target)}"`}>${e(guide.action)} ↗</button></p></div>`;
  return `<section class="ai-workspace agent-ai-workspace ai-chat-layout">
    <div class="ai-main">
      <div class="ai-toolbar"><span class="ai-status ${canUseTools?'ready':''}"><span></span>${e(badge)}</span><div class="ai-toolbar-actions"><button class="link-button" data-action="ai-refresh">Check connection</button><button class="link-button" data-view="connect">Connect your AI</button></div></div>
      <div class="ai-transcript agent-ai-chat" role="log" aria-label="Conversation with your agent">${transcript}</div>
      <form id="ai-form" class="ai-composer agent-ai-composer"><label for="ai-message">Your question</label><textarea id="ai-message" name="message" rows="3" maxlength="5000" placeholder="Tell Pull what you want to work on…">${e(assistantState.draft)}</textarea><div class="ai-composer-bottom"><span>${canUseTools?'Your running agent can reply here.':'Prepare a prompt for your own AI until an agent is connected.'}</span><button class="button primary" type="submit" ${assistantState.busy?'disabled':''}>${canUseTools?'Ask Pull':'Prepare prompt'} ${icon('arrow')}</button></div></form>
      ${canUseTools?`<div class="agent-ai-relay"><strong>${listening?'Agent recently active':'Your agent needs to be running'}</strong><p>${listening?'Replies appear in this conversation when your agent answers.':'An access key alone does not start an agent. Open your AI app and give it the relay instruction.'}</p><button class="link-button" data-action="ai-copy-relay">Copy agent startup instruction</button></div>`:''}
      ${assistantState.error?`<p class="agent-ai-error" role="alert">${e(assistantState.error)}</p>`:''}
      ${!canUseTools&&assistantState.preparedPrompt?`<div class="agent-ai-handoff" role="status"><div><span class="section-kicker">READY FOR YOUR AI APP</span><h3>Paste this into your assistant.</h3><p>Without MCP, your assistant knows only what you include here. Pull has not sent this question or received a model reply.</p></div><textarea id="ai-prepared-prompt" readonly rows="9" spellcheck="false">${e(assistantState.preparedPrompt)}</textarea><button class="button secondary" data-action="ai-copy-prompt">Copy prompt</button></div>`:''}
    </div>
    <aside class="ai-context agent-ai-aside"><div class="ai-context-head"><span class="section-kicker">WORKING WITH YOU</span><h3>Your context</h3>${icon('shield')}</div><div class="ai-context-business"><span>${state.context==='company'?'Company workspace':'Personal workspace'}</span><strong>${e(state.identity)}</strong><p>${state.offer?e(state.offer):'Add your offer so Pull understands who you help.'}</p><button class="link-button" data-action="workspace">Edit your brief</button></div><dl class="ai-context-details"><div><dt>Market</dt><dd>${e(state.rules.countries||'Worldwide')}</dd></div><div><dt>Audience</dt><dd>${e(state.rules.roles||'Not set')}</dd></div><div><dt>Reviewed prospects</dt><dd>${state.shortlist.length}</dd></div></dl><div class="agent-ai-access"><span class="badge ${canUseTools?'fit':'review'}">${canUseTools?'Relay permission ready':active?'Save needed':'MCP optional'}</span><p>${canUseTools?'An active relay key exists and this workspace is saved. Your agent must be running and checking for questions; a key alone does not prove the app is connected.':active?'Your relay key exists, but save your workspace to the cloud before using it here.':'You can use local guidance and prepare prompts now. Connect your own assistant for live conversation.'}</p>${!cloud.user?'<button class="link-button" data-action="account">Sign in</button>':active&&!saved?'<button class="link-button" data-action="account">Save to cloud</button>':'<button class="link-button" data-view="connect">Set up your AI ↗</button>'}</div><label class="ai-context-choice"><input id="ai-share-context" type="checkbox" ${assistantState.shareContext?'checked':''}><span>${canUseTools?'Ask my agent to use Pull tools':'Include my brief in the prompt'}</span></label><p class="ai-context-note">Pull does not add access keys or prospect contact details to a prepared prompt. Review what you share.</p><div class="ai-principle">${icon('shield')}<p>AI suggests.<br><strong>You decide.</strong><small>Evidence and permission still matter.</small></p></div></aside>
  </section>`;
}
